const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Point([142.4, -32.4]).buffer(15000); // 15km buffer around lake center
  const date1 = '2019-02-02';
  const date2 = '2021-05-14';

  // 2. Data Acquisition & Check
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function addWaterIndex(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Get images for 2019
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(lakeMenindee)
    .filterDate(date1, ee.Date(date1).advance(15, 'day'))
    .map(maskS2clouds)
    .map(addWaterIndex);

  const size1 = await col1.size().getInfo();
  console.log(`2019 Images found: ${size1}`);

  if (size1 === 0) {
    // Fallback to Landsat 8
    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeMenindee)
      .filterDate(date1, ee.Date(date1).advance(15, 'day'))
      .map(function(img) {
        const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
        return img.addBands(mndwi);
      });
    const size1_l8 = await col1.size().getInfo();
    console.log(`2019 Landsat fallback: ${size1_l8}`);
    if (size1_l8 === 0) {
      console.log("No data for 2019.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Get images for 2021
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(lakeMenindee)
    .filterDate(date2, ee.Date(date2).advance(15, 'day'))
    .map(maskS2clouds)
    .map(addWaterIndex);

  const size2 = await col2.size().getInfo();
  console.log(`2021 Images found: ${size2}`);

  if (size2 === 0) {
    // Fallback to Landsat 8
    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeMenindee)
      .filterDate(date2, ee.Date(date2).advance(15, 'day'))
      .map(function(img) {
        const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
        return img.addBands(mndwi);
      });
    const size2_l8 = await col2.size().getInfo();
    console.log(`2021 Landsat fallback: ${size2_l8}`);
    if (size2_l8 === 0) {
      console.log("No data for 2021.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Create median composites and detect water
  const img1 = col1.median();
  const img2 = col2.median();

  const water1 = img1.select('MNDWI').gt(0.3);
  const water2 = img2.select('MNDWI').gt(0.3);

  // 4. Calculate water area
  const pixelArea = ee.Image.pixelArea();

  const stats1 = await water1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMenindee,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await water2.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMenindee,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const area1 = stats1.MNDWI || 0;
  const area2 = stats2.MNDWI || 0;

  // Check valid pixel counts
  const count1 = await water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeMenindee,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const count2 = await water2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeMenindee,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  console.log(`2019 Water area: ${(area1/1e6).toFixed(2)} km², Valid pixels: ${count1.MNDWI || 0}`);
  console.log(`2021 Water area: ${(area2/1e6).toFixed(2)} km², Valid pixels: ${count2.MNDWI || 0}`);

  // 5. Validation & Final Answer
  if (!count1.MNDWI || !count2.MNDWI) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  const shrinkage = area1 - area2;
  const percentChange = ((shrinkage / area1) * 100).toFixed(1);
  console.log(`Change: ${(shrinkage/1e6).toFixed(2)} km² (${percentChange}%)`);

  if (area2 < area1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
